// Renders /api/report/<version>; offers to generate one (a background job) if it does not exist yet.
const $ = (id) => document.getElementById(id);
const esc = (s) => String(s ?? "").replace(/[&<>"]/g, (c) => ({"&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;"}[c]));
const pct = (x) => `${Math.round((x ?? 0) * 100)}%`;
const fmt = (v) => Array.isArray(v) ? (v.every((x) => x === v[0]) ? fmt(v[0]) : `[${v.map(fmt).join(", ")}]`) : (typeof v === "number" ? +v.toFixed(3) : esc(v));

async function versionParam() {
  const v = new URLSearchParams(location.search).get("v");
  if (v) return v;
  return (await (await fetch("/api/versions")).json()).live;
}

function marginView(m) {
  if (!m) return "";
  const bars = m.curve.map((f) => `<span class="${f >= 0.5 ? "f" : ""}" style="height:${Math.max(4, f * 100)}%"></span>`).join("");
  return `<div style="margin-top:10px"><b>Safety margin</b> on <span class="mono">${esc(m.condition)}</span>:
    nominal ${fmt(m.nominal)} → falls begin at <b>${m.starts_falling_at === null ? "never (within range)" : fmt(m.starts_falling_at)}</b>
    (attack used ${fmt(m.failing_value)})<div class="spark">${bars}</div>
    <span class="muted" style="font-size:12px">fall rate from nominal (left) to the attack's value (right)</span></div>`;
}

function render(r) {
  const s = r.summary || {};
  const t = r.totals;
  const live = r.version;
  $("report").innerHTML = `
    <span class="muted mono" style="font-size:12px">Unitree Go1 · policy ${esc(live)} · ${new Date(r.created * 1000).toLocaleString()}</span>
    <div class="headline">${esc(s.headline || "")}</div>
    <p>${esc(s.summary || "")}</p>
    <div class="stats">
      <div class="stat"><b>${t.attacks}</b><span>attacks tested (people, photos, agent)</span></div>
      <div class="stat"><b>${t.break_v1}</b><span>broke the original robot (v1)</span></div>
      <div class="stat"><b style="color:var(--crimson)">${t.break_now}</b><span>still break ${esc(live)}</span></div>
      <div class="stat"><b>${pct(r.gauntlet.v1)} → ${pct(r.gauntlet[live])}</b><span>falls on the locked 52-scenario gauntlet, v1 → ${esc(live)}</span></div>
    </div>
    <h2>Recommendations</h2>
    <ol class="recs">${(s.recommendations || []).map((x) => `<li>${esc(x)}</li>`).join("")}</ol>
    <h2>Failure families</h2>
    <div class="card"><table><tr><th>Family</th><th>Attacks</th><th>Broke v1</th><th>Still break ${esc(live)}</th></tr>
      ${r.families.map((f) => `<tr><td>${esc(f.family)}</td><td>${f.tried}</td><td>${f.break_v1}</td><td>${f.break_now}</td></tr>`).join("")}
    </table></div>
    <h2>Top findings</h2>
    ${r.findings.map((f) => `
      <div class="card finding">
        <video src="${f.clip}" muted loop playsinline controls></video>
        <div>
          <span class="sev ${f.fall_now >= 0.5 ? "open" : "fixed"}">${f.fall_now >= 0.5 ? "OPEN" : "FIXED"}</span>
          <span class="muted mono" style="font-size:12px"> ${esc(f.family)} · ${esc(f.source || "human")}${f.handle ? " · " + esc(f.handle) : ""}</span>
          <h3>"${esc(f.text)}"</h3>
          <div class="pills">${Object.entries(f.status || {}).map(([v, x]) => `<span class="pill ${x >= 0.5 ? "f" : "s"}">${esc(v)} ${pct(x)}</span>`).join("")}
            <span class="pill ${f.fall_now >= 0.5 ? "f" : "s"}">${esc(live)} now ${pct(f.fall_now)}</span></div>
          <pre class="mono" style="font-size:12px;white-space:pre-wrap;color:#c9cede">${esc(JSON.stringify(f.conditions))}</pre>
          ${f.diagnosis ? `<div><b>Muse Spark:</b> ${esc(f.diagnosis.mode)}: ${esc(f.diagnosis.what_happened)} <span class="muted">${esc(f.diagnosis.likely_cause)}</span></div>` : ""}
          ${marginView(f.margin)}
        </div>
      </div>`).join("")}
    <h2>Lineage</h2>
    <div class="lineage">${r.lineage.map((v) => `<div class="node ${v.name === live ? "live" : ""}"><b>${esc(v.name)}</b>${v.parent ? `from ${esc(v.parent)} · ${v.attacks} attacks` : "original"}</div>`).join("")}</div>
    <p class="muted" style="margin-top:28px;font-size:13px">Generated by Nemesis: attacks compiled to physics by Muse Wonder, simulated in MuJoCo MJX,
      clips diagnosed by Muse Spark, summary written by Muse Wonder. Margins: 11-point sweep × 16 seeds.</p>`;
}

async function generate(version) {
  $("report").innerHTML = `<p>No report for ${esc(version)} yet.</p><button class="go" id="gen">Generate red-team report</button><p class="mono muted" id="gs"></p>`;
  $("gen").onclick = async () => {
    $("gen").disabled = true;
    const res = await fetch("/api/report", {method: "POST", headers: {"Content-Type": "application/json"}, body: JSON.stringify({version})});
    const body = await res.json();
    if (!res.ok) { $("gs").textContent = "⚠ " + (body.detail || res.statusText); $("gen").disabled = false; return; }
    const es = new EventSource(`/api/jobs/${body.job}/events`);
    es.onmessage = (m) => {
      const e = JSON.parse(m.data);
      if (e.message) $("gs").textContent = e.message;
      if (e.stage === "done") { es.close(); load(); }
      if (e.stage === "failed") { es.close(); $("gs").textContent = "⚠ " + e.error; }
    };
  };
}

async function load() {
  const v = await versionParam();
  const res = await fetch(`/api/report/${encodeURIComponent(v)}`);
  if (res.ok) render(await res.json()); else generate(v);
}
load();
